		"policies": [
			{
				"source_page": 2177,
				"summary": "Consolidate company and subsidiaries; investments in affiliates owned 50% or less primarily China and Japan use equity method. No identified related VIE consolidated. U.S. GAAP estimates and local functional currencies."
			},
			{
				"source_page": 2178,
				"summary": "Revenue: owned restaurant cash sale net sales taxes; royalty and variable rent as franchisee sales occur; minimum rent straight-line; initial fees over generally 20-year term. Technology services principal/gross. PPE straight-line, buildings up to40years and equipment3–12years. Lease ROU/liability discounted, probable renewals, short-term exemption and nonlease-component election."
			},
			{
				"source_page": 2179,
				"summary": "Software amortized2–10years; long-lived asset impairment annual fourth-quarter/trigger tests at group then individual restaurant; goodwill reporting unit market, fair-value test; no current indicator and14.5m accumulated goodwill impairment. Advertising cooperatives generally unconsolidated."
			},
			{
				"source_page": 2180,
				"summary": "Uncertain tax positions more-likely-than-not; interest/penalties in tax expense. GILTI recognized as incurred. Fair-value hierarchy uses observable information; derivatives fair-valued."
			},
			{
				"source_page": 2181,
				"summary": "Derivatives gross and current/noncurrent by maturity; hedge fair-value changes affect AOCI or earnings based on designation. Debt fair value is separate from carrying amount."
			},
			{
				"source_page": 2182,
				"summary": "Fair-value hedges affect instrument and hedged debt; cash-flow hedges initially AOCI; net investment hedges translation OCI; undesignated derivative changes in earnings. No trading derivatives."
			},
			{
				"source_page": 2183,
				"summary": "EPS weighted-average shares and treasury stock method; antidilutive excluded. Cash equivalents original maturity90days or less."
			},
			{
				"source_page": 2185,
				"summary": "Franchise rent/royalty/initial fees separate lease/nonlease components. Deferred COVID rental/royalty cash collections fully recovered by2022year-end."
			},
			{
				"source_page": 2186,
				"summary": "ROU and liability include reasonably assured renewal options and discounted minimum payments; largely operating leases; incremental borrowing rate."
			},
			{
				"source_page": 2187,
				"summary": "Litigation accruals assessed matter-by-matter; recurring restaurant disposal gains and equity-method affiliate earnings within operating income."
			},
			{
				"source_page": 2189,
				"summary": "France settlement expense nonoperating and nondeductible; UTB gross and balance-sheet amounts distinct; subsequent IRS agreement February2023."
			},
			{
				"source_page": 2191,
				"summary": "Short-term obligations2.7bn classified long-term under long-term committed facility; debt adjusted for fair-value hedge and deferred debt costs."
			},
			{
				"source_page": 2192,
				"summary": "SBC grant-date fair value amortized generally straight-line; option pricing estimates; treasury stock supplies exercises."
			},
			{
				"source_page": 2193,
				"summary": "RSU cash/share settlement discretionary; performance RSUs TSR MonteCarlo; January2023strategy is subsequent event."
			}
		],
